# Review package: 6d271f9..HEAD

## Commits
b1261f6 test: use typographic quotes in curved-quote sentenceCount test

## Files changed
 test/sentenceCount.test.js | 2 +-
 1 file changed, 1 insertion(+), 1 deletion(-)

## Diff
diff --git a/test/sentenceCount.test.js b/test/sentenceCount.test.js
index b3169c0..9ae950d 100644
--- a/test/sentenceCount.test.js
+++ b/test/sentenceCount.test.js
@@ -157,21 +157,21 @@ test('still breaks at a real sentence end that comes before a title', () => {

 test('keeps a closing quote with the sentence it ends', () => {
   assert.equal(sentenceCount('"Stop!" she said. "Please." He stopped.'), 4);
 });

 test('keeps a closing bracket with the sentence it ends', () => {
   assert.equal(sentenceCount('The lamp (the old one.) was lit. It burned.'), 3);
 });

 test('handles curved quotes at sentence boundaries', () => {
-  assert.equal(sentenceCount('He said "Stop." Then left.'), 2);
+  assert.equal(sentenceCount('He said \u201cStop.\u201d Then left.'), 2);
 });

 test('does not count a terminator inside a word', () => {
   assert.equal(sentenceCount('a.b.c is not a sentence break'), 1);
 });

 test('counts sentences across newlines', () => {
   assert.equal(sentenceCount('First line.\nSecond line.\n\nThird line.'), 3);
 });

